pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000, "TKN", "TKN"); }
    function testRegression_property() public {
        vm.prank(c.owner());
        c.mintToken(c.owner(), 500);
        uint256 balanceBefore = c.balanceOf(c.owner());
        vm.prank(c.owner());
        c.burn(300);
        uint256 balanceAfter = c.balanceOf(c.owner());
        assertTrue(balanceAfter == balanceBefore - 300);
    }
}
